var EGYES_SZO = { "nulla": 0, "egy": 1, "ketto": 2, "kettő": 2, "ket": 2, "harom": 3, "három": 3, "negy": 4, "négy": 4, "ot": 5, "öt": 5, "hat": 6, "het": 7, "hét": 7, "nyolc": 8, "kilenc": 9 };
