    + '<circle class="kt-lampas-lang" cx="0" cy="-56" r="3.6" fill="#fff4c2"/>';
  if (id === "szokokut") return arny.replace("RX", 40).replace("RY", 11)
    + '<ellipse cx="0" cy="-4" rx="40" ry="13" fill="url(#ko-stone)"/>'
