  s += '<g fill="#ffffff" opacity="0.28"><path d="M-30 336 L-18 336 L-44 436 L-60 436 Z"/><path d="M-12 340 L-6 340 L-20 436 L-28 436 Z"/></g>';   /* fénysugarak */
