    chips += '<button class="kert-trukk-chip' + (ulAkt ? ' aktiv' : '') + '" data-id="' + t.id + '" aria-label="' + t.nev + '">' +
      '<span class="ktr-emoji">' + t.emoji + '</span><span class="ktr-nev">' + (ulAkt ? "Feláll" : t.nev) + '</span></button>';
