        var par = (L.length % 2) ? i : i + Math.floor(i / L.length);
        var muv = (r.muvelet === "osszeadas" || r.muvelet === "kivonas") ? r.muvelet : (par % 2 ? "kivonas" : "osszeadas");
        var o = egyeniOsszeadoCfg(L[i % L.length], muv); o.darab = darab;
        st.push(o);
